import{z as r,x as E,o,c as d,q as l,j as i,D as e,d as n,s as c,S as s}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"MCP 与工具生态","description":"","frontmatter":{"title":"MCP 与工具生态","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mcp.md","filePath":"llm/mcp.md","lastUpdated":1791413859000}'),p={name:"llm/mcp.md"};function A(m,a,B,h,C,P){const t=E("Mermaid");return o(),d("div",null,[a[2]||(a[2]=l('<h1 id="mcp-与工具生态" tabindex="-1">MCP 与工具生态 <a class="header-anchor" href="#mcp-与工具生态" aria-label="Permalink to &quot;MCP 与工具生态&quot;">​</a></h1><div class="epigraph"><p>用开放协议把上下文与工具从各家专有插件里抽出来：宿主负责对话与模型，服务器负责数据源与副作用，中间是可发现的 JSON-RPC。</p><footer>—— Anthropic，Model Context Protocol 公开规范与 2024 年 11 月公告</footer></div><p>Function calling 解决的是「这一次 HTTP 请求里有哪些函数」。应用一多，每个桌面客户端、每个 IDE、每个 Agent 运行时都要为 GitHub、数据库、文件系统各写一套适配，工具生态按客户端数量叉乘。Anthropic 提出的 Model Context Protocol（MCP）把这层适配收成开放协议：MCP 服务器暴露工具、资源与提示模板；MCP 客户端跑在宿主（聊天应用、IDE、自动化运行时）里，负责发现、鉴权与把调用翻译成模型能看的消息。它不是新的基座模型，也不是 ReAct 算法，而是工具与上下文的 USB-C。本篇写宿主—客户端—服务器的边界、三类原语、以及它和 <a href="/llm/function-calling">function calling</a> 信封如何衔接。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>专有插件把「怎么连上数据」锁在某一家产品里。换宿主就要重写连接器；同一份 Postgres 在 IDE 与聊天应用里各维护一套 SQL 工具描述，描述漂移后模型调用行为也漂移。另一方面，把所有工具静态写进每次 Chat Completions 的 <code>tools</code> 数组，清单会随安装的集成线性膨胀，上下文被说明书占满，权限也无法按服务器隔离。需要运行时发现、按服务器进程隔离密钥、以及与模型厂商无关的传输。</p><p>协议还必须允许非工具的上下文：一整份文件、一组数据库 schema、一段可复用的提示词，并不都适合做成「函数」。若只提供 function calling，宿主只能把文件内容塞进 system prompt，缓存与访问控制都变粗糙。MCP 把资源（可读的数据）和提示（可复用的消息模板）从工具（有副作用的动作）里分开，问题设定比「再包一层 JSON 函数」更宽。</p><p><span class="marginnote">算一笔清单账：一个工具的名称、描述加 JSON Schema 常占一两百 token。装 40 个集成、每个 5 个工具，光「说明书」就可能吃掉上万 token 的上下文，而模型每次真正要用的只有两三个——这正是静态 <code>tools</code> 数组在集成变多后难以为继的原因。</span></p><h3 id="宿主、客户端、服务器" tabindex="-1">宿主、客户端、服务器 <a class="header-anchor" href="#宿主、客户端、服务器" aria-label="Permalink to &quot;宿主、客户端、服务器&quot;">​</a></h3><p>宿主是用户面对的应用，拥有模型调用、UI 与最终权限提示。客户端是宿主内的协议栈，维护与各服务器的会话。服务器是独立进程或远程服务，实现工具与资源，通常用 stdio 跑在本地，或用 HTTP 流式传输跑在远程。初始化时双方交换协议版本与能力集：服务器声明自己有 tools / resources / prompts 中的哪些；客户端声明自己是否允许服务器反向请求模型采样。能力未声明的方法不应被调用。</p><p><span class="marginnote">MCP 服务器拿到的密钥属于该数据源，不应等于宿主的模型 API key。反过来，服务器若被授予「代宿主调用模型」（sampling），就相当于把补全能力借给不可信进程。默认应关 sampling，只保留工具与只读资源。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>传输层是 JSON-RPC 2.0：请求有方法名与 id，响应匹配 id，通知无响应。本地开发常用 stdio，一条消息一行，便于把服务器写成任意语言的小进程。远程则走带会话的 HTTP 流，以便多客户端连同一数据源。握手之后，客户端调用 <code>tools/list</code> 得到名称、描述与 input schema，再在用户打开某连接器时把子集登记进当前对话的工具表。调用走 <code>tools/call</code>，参数是结构化对象，结果是文本或内容块（含图片等），由客户端改写成模型侧的 tool 观察。</p><p>资源用 URI 标识，<code>resources/list</code> / <code>resources/read</code> 把文件、工单、表结构读成模型上下文。提示模板 <code>prompts/list</code> / <code>prompts/get</code> 让服务器提供带参数的消息草稿（例如「根据这份 schema 写查询」），减少每个宿主各写各的 system prompt。这三类都可以在运行时通过通知做变更：工具列表热更新后，宿主应重新同步，而不是沿用进程启动时的一份静态 JSON。</p>',13)),(o(),i(s,null,{default:e(()=>[c(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20LR%0A%20%20H%5B%22%E5%AE%BF%E4%B8%BB%E5%BA%94%E7%94%A8%20%2F%20%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20C%5B%22MCP%20%E5%AE%A2%E6%88%B7%E7%AB%AF%22%5D%0A%20%20C%20--%3E%20S1%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%EF%BC%9A%E4%BB%93%E5%BA%93%22%5D%0A%20%20C%20--%3E%20S2%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%EF%BC%9A%E6%95%B0%E6%8D%AE%E5%BA%93%22%5D%0A%20%20C%20--%3E%20S3%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%EF%BC%9A%E6%96%87%E4%BB%B6%E7%B3%BB%E7%BB%9F%22%5D%0A%20%20S1%20--%3E%20T%5B%22tools%20%2F%20resources%20%2F%20prompts%22%5D%0A%20%20S2%20--%3E%20T%0A%20%20S3%20--%3E%20T%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l('<h3 id="三类原语-工具、资源、提示" tabindex="-1">三类原语：工具、资源、提示 <a class="header-anchor" href="#三类原语-工具、资源、提示" aria-label="Permalink to &quot;三类原语：工具、资源、提示&quot;">​</a></h3><p>工具对应有副作用或查询语义的函数，input schema 与 function calling 的 parameters 同构，因此客户端可以一对一地翻译成 <code>tools</code> 字段。资源是可寻址的只读（或可订阅）数据，适合当检索语料或 schema 目录，而不必为「读第 3 页」发明一个函数。提示是服务器维护的对话草稿，适合把领域诀窍留在连接器里而不是散落在各宿主的提示库。把读文件全部实现成工具也能用，但会失去 URI、订阅与「当上下文而不是当动作」的语义，日志和缓存都会变差。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>对模型而言，MCP 通常是透明的：它仍然看见 function calling 风格的名字与 JSON 参数，或看见被贴进前缀的资源文本。协议的价值在 <em>发现与隔离</em>。发现使工具清单随已连接服务器变化；隔离使崩溃、限流、密钥泄漏以服务器为边界。JSON-RPC 的 id 把一次 <code>tools/call</code> 与结果对齐，并行调用可以在客户端映射为并行 function calling 的多个 <code>tool_call_id</code>。资源读入会增加预填充长度，应有体积上限，否则一次 <code>resources/read</code> 就能把上下文窗打满。</p>',4)),(o(),i(s,null,{default:e(()=>[c(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E6%A8%A1%E5%9E%8B%E9%87%87%E6%A0%B7%E5%B7%A5%E5%85%B7%E5%90%8D%E4%B8%8E%E5%8F%82%E6%95%B0%22%5D%20--%3E%20V%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E6%8C%89%20schema%20%E6%A0%A1%E9%AA%8C%22%5D%0A%20%20V%20--%3E%20J%5B%22JSON-RPC%20tools%2Fcall%20%E5%B8%A6%20id%22%5D%0A%20%20J%20--%3E%20SV%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%E8%BF%9B%E7%A8%8B%E6%89%A7%E8%A1%8C%E5%89%AF%E4%BD%9C%E7%94%A8%22%5D%0A%20%20SV%20--%3E%20RB%5B%22%E7%BB%93%E6%9E%9C%E5%86%85%E5%AE%B9%E5%9D%97%E6%8C%89%20id%20%E5%9B%9E%E4%BC%A0%22%5D%0A%20%20RB%20--%3E%20OB%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E8%AF%91%E6%88%90%20tool%20%E8%A7%82%E5%AF%9F%22%5D%0A%20%20OB%20--%3E%20CT%5B%22%E5%B9%B6%E5%85%A5%E4%B8%8A%E4%B8%8B%E6%96%87%E7%BB%A7%E7%BB%AD%E7%94%9F%E6%88%90%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=l('<p>生态上的网络效应来自「写一次服务器、挂多个宿主」。这要求 schema 与错误形状稳定，否则模型在 A 宿主学到的调用在 B 宿主因描述不同而失败。它不规定检索算法：服务器内部可以是 <a href="/llm/hybrid-retrieval">混合检索</a> 或一次 SQL。也不规定多步策略：循环仍是宿主的 <a href="/llm/react">ReAct</a> 或规划器。MCP 只保证「有一个地方能列出并调用工具」。</p><p><span class="marginnote">「id 对齐」就是给每次调用发一个取餐号：请求带 7 号，结果也标 7 号，客户端据此把结果送回对应的那一次调用。并行发起十个调用也不会串线，这是 JSON-RPC 免费送的能力，协议只是把它用在工具调用上。</span></p><p><span class="marginnote">不要把 MCP 写成「Anthropic 模型专用」。规范是开放的；宿主可以接任何实现了 chat 与工具字段的后端。反过来，接了 MCP 也不等于模型会用工具——模板、微调数据和 <code>tool_choice</code> 仍然决定行为。</span></p><h3 id="与专有-function-calling-的关系" tabindex="-1">与专有 function calling 的关系 <a class="header-anchor" href="#与专有-function-calling-的关系" aria-label="Permalink to &quot;与专有 function calling 的关系&quot;">​</a></h3><p>Function calling 是模型 I/O 契约；MCP 是工具进程与宿主之间的契约。两者叠在一起：MCP 的 list/call 填满 function calling 的声明与执行。没有 MCP 时，宿主把硬编码函数当执行器，仍然可以做 function calling。没有 function calling、只把 MCP 资源塞进提示，模型只能读不能按 schema 调动作。产品上应先有执行白名单，再考虑是否用 MCP 做发现，而不是为了「生态」把不可信服务器连进生产。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>MCP 不解决工具幻觉、不解决 JSON 参数错误，那些仍靠描述质量、<a href="/llm/json-schema-decode">结构化输出</a> 与执行层校验。它也不替代企业服务网格：认证、审计、多租户配额要做在宿主或网关上。远程服务器把数据面暴露到网络，威胁模型与本地 stdio 不同，不能共用一份「反正是官方连接器」的信任假设。规范会演进（传输从早期 SSE 到后续流式 HTTP），客户端应声明对齐的协议版本，而不是声称追踪每一天的草稿。</p><p><span class="marginnote">为什么本地与远程要分开对待：stdio 服务器跑在你本机，默认继承你的登录权限与文件访问；远程服务器把同一套 tools/list 暴露到公网，任何人都能尝试握手。同一份配置直接搬家，等于把「本机已登录」的隐含信任一起带上了网。</span></p><p>不要为每个内部微服务都写一个 MCP 服务器，除非真有多种宿主要复用。内部只跑一个 Agent 运行时，直接函数分发更短。也不要把高权限 shell 做成通用 MCP 工具再交给通用模型。评测生态时分开：协议互操作（能否 list/call）、模型用工具成功率、服务器实现正确性。三者失败形态不同。</p><p><span class="marginnote">出处是 Anthropic 的 MCP 规范与公告、JSON-RPC 2.0。没有一篇叫「MCP」的经典 NeurIPS 论文；不要把连接器博客的延迟数字写进协议定义。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MCP 用 JSON-RPC 让宿主发现并调用外部服务器上的工具、资源与提示，解决的是生态与隔离，不是新的推理算法。</li><li>宿主拥有 UI 与模型；服务器拥有数据源密钥；sampling 反向调用默认应关。</li><li>工具与 function calling 的 schema 同构，便于翻译；资源与提示覆盖「不是函数」的上下文。</li><li>对模型通常透明，价值在运行时清单、进程隔离与一次编写多宿主复用。</li><li>不替代鉴权、检索算法或多步 Agent 循环。</li><li>协议版本与传输要显式对齐；远程与本地的威胁模型不同。</li><li>出处：Anthropic Model Context Protocol 规范与 2024 年 11 月公告；JSON-RPC 2.0。</li></ul>',12))])}const _=r(p,[["render",A]]);export{f as __pageData,_ as default};
